<div id="taskModal" class="modal"><div class="modal-content"><form action="dashboard.php" method="POST"><input type="hidden" name="action" value="add_task"><div class="modal-header" style="color: #6c757d;">Assign Housekeeping Task</div><div class="form-group"><label>Room Number</label><input type="text" name="room_number" class="form-control" placeholder="e.g. A04" required></div><div class="form-group"><label>Assign Operational Staff</label><select name="assigned_staff" class="form-select" required><?php foreach($staff_arr as $s): ?><?php if($s['department'] == 'Housekeeping'): ?><option value="<?php echo $s['staff_id']; ?>"><?php echo htmlspecialchars($s['fullname']); ?></option><?php endif; ?><?php endforeach; ?></select></div><div class="form-group"><label>Initial Status</label><select name="task_status" class="form-select"><option value="Pending">Pending</option><option value="In Progress">In Progress</option><option value="Completed">Completed</option></select></div><div class="modal-footer"><button type="button" class="btn-close" onclick="closeModal('taskModal')">Cancel</button><button type="submit" class="btn btn-primary">Save Assignment</button></div></form></div></div>
    <div id="maintenanceModal" class="modal"><div class="modal-content"><form action="dashboard.php" method="POST"><input type="hidden" name="action" value="add_maintenance"><div class="modal-header" style="color: #dc3545;">Log Maintenance Request</div><div class="form-group"><label>Fault Room Location</label><input type="text" name="room_number" class="form-control" placeholder="e.g. B03" required></div><div class="form-group"><label>Issue Description</label><textarea name="issue_description" class="form-control" rows="3" placeholder="Describe the maintenance issue..." required></textarea></div><div class="form-group"><label>Priority Escalation</label><select name="priority" class="form-select"><option value="Low">Low</option><option value="Medium">Medium</option><option value="High">High</option></select></div><div class="form-group"><label>Assign Technician</label><select name="assigned_staff" class="form-select" required><?php foreach($staff_arr as $s): ?><?php if($s['department'] == 'Maintenance'): ?><option value="<?php echo $s['staff_id']; ?>"><?php echo htmlspecialchars($s['fullname']); ?></option><?php endif; ?><?php endforeach; ?></select></div><div class="modal-footer"><button type="button" class="btn-close" onclick="closeModal('maintenanceModal')">Cancel</button><button type="submit" class="btn btn-danger">Log Fault</button></div></form></div></div>
    <script>
        function openModal(id) { document.getElementById(id).style.display = 'flex'; }
        function closeModal(id) { document.getElementById(id).style.display = 'none'; }
        window.onclick = function(event) { if (event.target.className === 'modal') { event.target.style.display = 'none'; } }
    </script>
</body>
</html>